1	package cli
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"time"
9	)
10	
11	const brainManifestSchemaVersion = 3
12	
13	type brainSources struct {
14		Seed     *seedSourceManifest     `json:"seed,omitempty"`
15		Sessions *sessionSourceManifest  `json:"sessions,omitempty"`
16		Semantic *semanticSourceManifest `json:"semantic,omitempty"`
17		History  *historySourceManifest  `json:"history,omitempty"`
18	}
19	
20	type sessionSourceManifest struct {
21		GeneratedAt        time.Time       `json:"generated_at"`
22		EntireCLIVersion   string          `json:"entire_cli_version,omitempty"`
23		DefaultBranch      string          `json:"default_branch,omitempty"`
24		TranscriptMode     string          `json:"transcript_mode"`
25		Scope              string          `json:"scope"`
26		CheckpointLimit    int             `json:"checkpoint_limit"`
27		CheckpointsScanned int             `json:"checkpoints_scanned"`
28		OldestSessionAt    *time.Time      `json:"oldest_session_at,omitempty"`
29		LatestCheckpointID string          `json:"latest_checkpoint_id,omitempty"`
30		Branches           []exportBranch  `json:"branches,omitempty"`
31		Sessions           []exportSession `json:"sessions"`
32		Warnings           []string        `json:"warnings,omitempty"`
33	}
34	
35	func loadBrainManifest(outputDir string) (*exportManifest, error) {
36		path := filepath.Join(outputDir, exportManifestFileName)
37		data, err := os.ReadFile(path)
38		if err != nil {
39			if os.IsNotExist(err) {
40				return &exportManifest{SchemaVersion: brainManifestSchemaVersion}, nil
41			}
42			return nil, fmt.Errorf("read brain manifest: %w", err)
43		}
44		var manifest exportManifest
45		if err := json.Unmarshal(data, &manifest); err != nil {
46			return nil, fmt.Errorf("parse brain manifest: %w", err)
47		}
48		normalizeBrainManifest(&manifest)
49		return &manifest, nil
50	}
51	
52	func normalizeBrainManifest(manifest *exportManifest) {
53		if manifest.SchemaVersion == 0 {
54			manifest.SchemaVersion = 1
55		}
56		if manifest.Sources == nil {
57			manifest.Sources = &brainSources{}
58		}
59		if manifest.Sources.Sessions == nil && (len(manifest.Sessions) > 0 || manifest.TranscriptMode != "" || manifest.CheckpointsScanned > 0) {
60			manifest.Sources.Sessions = sessionSourceFromExport(*manifest)
61		}
62	}
63	
64	func sessionSourceFromExport(manifest exportManifest) *sessionSourceManifest {
65		return &sessionSourceManifest{
66			GeneratedAt:        manifest.GeneratedAt,
67			EntireCLIVersion:   manifest.EntireCLIVersion,
68			DefaultBranch:      manifest.DefaultBranch,
69			TranscriptMode:     manifest.TranscriptMode,
70			Scope:              manifest.Scope,
71			CheckpointLimit:    manifest.CheckpointLimit,
72			CheckpointsScanned: manifest.CheckpointsScanned,
73			OldestSessionAt:    oldestSessionAt(manifest.Sessions),
74			LatestCheckpointID: latestCheckpointID(manifest.Sessions),
75			Branches:           append([]exportBranch(nil), manifest.Branches...),
76			Sessions:           append([]exportSession(nil), manifest.Sessions...),
77			Warnings:           append([]string(nil), manifest.Warnings...),
78		}
79	}
