81	func oldestSessionAt(sessions []exportSession) *time.Time {
82		var oldest time.Time
83		for _, session := range sessions {
84			if session.CreatedAt.IsZero() {
85				continue
86			}
87			if oldest.IsZero() || session.CreatedAt.Before(oldest) {
88				oldest = session.CreatedAt.UTC()
89			}
90		}
91		if oldest.IsZero() {
92			return nil
93		}
94		return &oldest
95	}
96	
97	func latestCheckpointID(sessions []exportSession) string {
98		var latest exportSession
99		for _, session := range sessions {
100			if latest.SessionID == "" || shouldReplaceExportSession(latest, session) {
101				latest = session
102			}
103		}
104		return latest.LatestCheckpoint
105	}
