107	func shouldReplaceExportSession(current, candidate exportSession) bool {
108		if candidate.CreatedAt.After(current.CreatedAt) {
109			return true
110		}
111		if current.CreatedAt.Equal(candidate.CreatedAt) {
112			return candidate.LatestCheckpoint > current.LatestCheckpoint
113		}
114		return false
115	}
