121		}
122		if existing.Sources == nil {
123			existing.Sources = &brainSources{}
124		}
125		sessionManifest.SchemaVersion = brainManifestSchemaVersion
126		sessionManifest.RepoKey = repoKey
127		sessionManifest.Sources = existing.Sources
128		sessionManifest.Sources.Sessions = sessionSourceFromExport(sessionManifest)
129		if existing.Sources.Seed != nil {
130			sessionManifest.Sources.Seed = existing.Sources.Seed
131		}
132		if existing.Sources.Semantic != nil {
133			sessionManifest.Sources.Semantic = existing.Sources.Semantic
134		}
135		return writeBrainManifestAndReadme(outputDir, sessionManifest)
136	}
