138	func writeBrainSeedSource(outputDir, repoKey string, seed *seedSourceManifest) error {
139		manifest, err := loadBrainManifest(outputDir)
140		if err != nil {
141			return err
142		}
143		if manifest.Sources == nil {
144			manifest.Sources = &brainSources{}
145		}
146		manifest.SchemaVersion = brainManifestSchemaVersion
147		manifest.RepoKey = repoKey
148		manifest.GeneratedAt = seed.GeneratedAt
149		if manifest.GeneratedAt.IsZero() {
150			manifest.GeneratedAt = time.Now().UTC()
151		}
152		manifest.Sources.Seed = seed
153		applySessionSourceAliases(manifest)
154		return writeBrainManifestAndReadme(outputDir, *manifest)
155	}
156	
157	func applySessionSourceAliases(manifest *exportManifest) {
158		if manifest.Sources == nil || manifest.Sources.Sessions == nil {
159			return
160		}
161		sessions := manifest.Sources.Sessions
162		manifest.EntireCLIVersion = sessions.EntireCLIVersion
163		manifest.DefaultBranch = sessions.DefaultBranch
164		manifest.TranscriptMode = sessions.TranscriptMode
165		manifest.Scope = sessions.Scope
166		manifest.CheckpointLimit = sessions.CheckpointLimit
167		manifest.CheckpointsScanned = sessions.CheckpointsScanned
168		manifest.Branches = append([]exportBranch(nil), sessions.Branches...)
169		manifest.Sessions = append([]exportSession(nil), sessions.Sessions...)
170		manifest.Warnings = append([]string(nil), sessions.Warnings...)
171	}
172	
173	func writeBrainManifestAndReadme(outputDir string, manifest exportManifest) error {
174		normalizeBrainManifest(&manifest)
175		manifest.SchemaVersion = brainManifestSchemaVersion
176		data, err := json.MarshalIndent(manifest, "", "  ")
177		if err != nil {
178			return fmt.Errorf("encode %s: %w", exportManifestFileName, err)
179		}
180		data = append(data, '\n')
181		if err := writeFileAtomic(filepath.Join(outputDir, exportManifestFileName), data, 0o600); err != nil {
182			return fmt.Errorf("write %s: %w", exportManifestFileName, err)
183		}
184		if err := writeFileAtomic(filepath.Join(outputDir, exportReadmeFileName), []byte(renderBrainReadme(manifest)), 0o600); err != nil {
185			return fmt.Errorf("write brain readme: %w", err)
186		}
187		return nil
188	}
