190	func writeFileAtomic(path string, data []byte, perm os.FileMode) error {
191		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
192			return err
193		}
194		tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
195		if err != nil {
196			return err
197		}
198		tmpName := tmp.Name()
199		cleanup := true
200		defer func() {
201			if cleanup {
202				_ = os.Remove(tmpName)
203			}
204		}()
205		if _, err := tmp.Write(data); err != nil {
206			_ = tmp.Close()
207			return err
208		}
209		if err := tmp.Chmod(perm); err != nil {
210			_ = tmp.Close()
211			return err
212		}
213		if err := tmp.Close(); err != nil {
214			return err
215		}
216		if err := os.Rename(tmpName, path); err != nil {
217			return err
218		}
219		cleanup = false
220		return nil
221	}
222	
223	func renderBrainReadme(manifest exportManifest) string {
224		if manifest.Sources == nil || (manifest.Sources.Seed == nil && manifest.Sources.Semantic == nil && manifest.Sources.History == nil) {
225			return renderExportReadme(manifest)
226		}
227		return renderCombinedBrainReadme(manifest)
228	}
