2110	const semanticParseErrorCode = "E_PARSE_ERROR"
2111	
2112	// semanticParseErrorTolerance is the fraction of indexed files that may carry
2113	// only benign parse errors before the brain is reported as degraded. Below this
2114	// threshold the completeness axis stays ok; the failures remain recorded in the
2115	// semantic source so they can still be inspected and acted on. Above it, the
2116	// volume is high enough to suspect a grammar/provider problem worth surfacing.
2117	const semanticParseErrorTolerance = 0.10
2118	
2119	// semanticCompletenessAxis classifies partial provider failures. Failures that
2120	// are exclusively benign parse errors and stay under the tolerance fraction keep
2121	// the axis ok; anything else (a non-parse failure code, an uncountable file set,
2122	// or too many parse errors) degrades the brain.
2123	func semanticCompletenessAxis(source *semanticSourceManifest) staleAxis {
2124		failures := len(source.PartialFailures)
2125		parseErrors := 0
2126		for _, failure := range source.PartialFailures {
2127			if failure.Code == semanticParseErrorCode {
2128				parseErrors++
2129			}
2130		}
2131		if parseErrors == failures && source.Files > 0 {
2132			fraction := float64(failures) / float64(source.Files)
2133			if fraction < semanticParseErrorTolerance {
2134				return staleAxis{State: "ok", Detail: fmt.Sprintf("%d/%d files had tolerated parse errors", failures, source.Files)}
2135			}
2136			return staleAxis{State: "degraded", Detail: fmt.Sprintf("%d partial failures in %.0f%% of files", failures, fraction*100)}
2137		}
2138		return staleAxis{State: "degraded", Detail: strconv.Itoa(failures) + " partial failures"}
